using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace KetPsi.Endpoints.Http.Generator;

/// <summary>Source emission for both modes (classic Minimal API lambdas and the KetPsi request-delegate path).</summary>
internal static class Emitter
{
    public const string Aot = "__KetPsiAot";
    private const string Task = "global::System.Threading.Tasks.Task";

    private const string FileHeader =
        "// <auto-generated/>\n" +
        "#nullable enable annotations\n" +
        "#pragma warning disable CS0612, CS0618, CS1591, CS8019\n";

    // ------------------------------------------------------------------
    // Fluent builder stubs per handler
    // ------------------------------------------------------------------

    public static string BuilderExtensions(string className, HandlerBuilderModel handler)
    {
        var w = new CodeWriter();
        w.Raw(FileHeader);
        w.Line("using KetPsi.Endpoints.Abstractions;");
        w.Line("using KetPsi.Endpoints.Http;");
        w.Line();
        w.Open("namespace KetPsi.Endpoints.Http");
        w.Open($"{handler.Accessibility} static class {className}HttpEndpointBuilderExtensions");
        foreach (var param in handler.Parameters)
        {
            var accessibility = handler.Accessibility == "internal" || param.Accessibility == "internal" ? "internal" : "public";
            w.Line($"{accessibility} static IHttpParameterBuilder<{param.TypeName}> @{Parsing.ToPascalCase(param.Name)}(this IHttpEndpointBuilder<{handler.HandlerFqn}> builder) => default!;");
        }
        w.Close();
        w.Close();
        return w.ToString();
    }

    public static string Master(IReadOnlyList<string> classNames)
    {
        var w = new CodeWriter();
        w.Raw(FileHeader);
        w.Line("using Microsoft.AspNetCore.Builder;");
        w.Line("using Microsoft.AspNetCore.Routing;");
        w.Line("using Microsoft.Extensions.DependencyInjection;");
        w.Line();
        w.Open("namespace Microsoft.AspNetCore.Builder");
        w.Open("public static class HttpEndpointExtensions");
        w.Open("public static IEndpointRouteBuilder MapHttpEndpoints(this WebApplication app)");
        foreach (var name in classNames)
            w.Line($"app.Map{name}Endpoints();");
        w.Line("return app;");
        w.Close();
        w.Line();
        w.Open("public static IServiceCollection AddHttpEndpoints(this IServiceCollection services)");
        foreach (var name in classNames)
            w.Line($"services.Add{name}HttpEndpoints();");
        w.Line("return services;");
        w.Close();
        w.Close();
        w.Close();
        return w.ToString();
    }

    public static string Activation(GeneratorOptions options)
        => "// <auto-generated/>\n" +
           $"// PublishAot raw='{options.RawPublishAot}' resolved={(options.PublishAot ? "True" : "False")}\n" +
           $"// EnableRequestDelegateGenerator raw='{options.RawEnableRdg}' resolved={(options.EnableRdg ? "True" : "False")}\n" +
           $"// useKetPsiRequestDelegate={(options.UseRequestDelegate ? "True" : "False")}\n" +
           "namespace KetPsi.Endpoints.Http.Generated;\n" +
           "internal static class KetPsiRdgActivation\n" +
           "{\n" +
           $"    public const bool UseKetPsiRequestDelegate = {(options.UseRequestDelegate ? "true" : "false")};\n" +
           "}\n";

    // ------------------------------------------------------------------
    // Per mapping class
    // ------------------------------------------------------------------

    public static string MappingClass(string className, IReadOnlyList<EndpointModel> endpoints, bool useRequestDelegate)
    {
        var usings = new SortedSet<string>(StringComparer.Ordinal)
        {
            "using Microsoft.AspNetCore.Builder;",
            "using Microsoft.AspNetCore.Http;",
            "using Microsoft.AspNetCore.Routing;",
            "using Microsoft.AspNetCore.Mvc;",
            "using Microsoft.Extensions.DependencyInjection;",
            "using KetPsi.Endpoints.Abstractions;",
            "using KetPsi.Endpoints.Http;",
        };
        foreach (var ep in endpoints)
        {
            foreach (var u in ep.Usings)
                usings.Add(u);
        }

        var w = new CodeWriter();
        w.Raw(FileHeader);
        foreach (var u in usings)
            w.Line(u);
        w.Line($"using {Aot} = global::KetPsi.Endpoints.Http.Aot;");
        w.Line();
        w.Open("namespace Microsoft.AspNetCore.Builder");
        w.Open($"public static class {className}HttpEndpointExtensions");

        // AsParameters surrogate structs (deduplicated by name).
        var emitted = new HashSet<string>(StringComparer.Ordinal);
        foreach (var ep in endpoints)
        {
            foreach (var p in ep.Parameters)
            {
                if (p.UseSurrogate && p.Dto is not null && emitted.Add(SurrogateName(ep, p)))
                    EmitSurrogate(w, SurrogateName(ep, p), p.Dto);
            }
        }

        // Group variables.
        var body = new CodeWriter(3);
        var groupVars = new Dictionary<string, string>(StringComparer.Ordinal);
        var builderVars = new string[endpoints.Count];
        for (var i = 0; i < endpoints.Count; i++)
        {
            var parent = "app";
            var key = new StringBuilder("app");
            foreach (var step in endpoints[i].Receiver.Steps)
            {
                key.Append(step);
                var k = key.ToString();
                if (!groupVars.TryGetValue(k, out var groupVar))
                {
                    groupVar = "__kp_group" + groupVars.Count.ToString(System.Globalization.CultureInfo.InvariantCulture);
                    groupVars[k] = groupVar;
                    body.Line($"var {groupVar} = {parent}{step};");
                }
                parent = groupVar;
            }
            builderVars[i] = parent;
        }

        if (groupVars.Count > 0)
            body.Line();

        for (var i = 0; i < endpoints.Count; i++)
        {
            if (useRequestDelegate)
                new RequestDelegateEndpoint(endpoints[i], i).EmitRegistration(body, builderVars[i]);
            else
                EmitClassicRegistration(body, endpoints[i], builderVars[i]);
        }

        if (useRequestDelegate)
        {
            for (var i = 0; i < endpoints.Count; i++)
                new RequestDelegateEndpoint(endpoints[i], i).EmitMembers(w);
        }

        w.Open($"public static IEndpointRouteBuilder Map{className}Endpoints(this WebApplication app)");
        w.Raw(body.ToString());
        w.Line("return app;");
        w.Close();
        w.Line();

        w.Open($"public static IServiceCollection Add{className}HttpEndpoints(this IServiceCollection services)");
        foreach (var handler in endpoints.Where(e => !e.IsStatic).Select(e => e.HandlerFqn).Distinct(StringComparer.Ordinal))
            w.Line($"global::Microsoft.Extensions.DependencyInjection.Extensions.ServiceCollectionDescriptorExtensions.TryAddTransient<{handler}>(services);");
        w.Line("return services;");
        w.Close();

        w.Close();
        w.Close();
        return w.ToString();
    }

    // ------------------------------------------------------------------
    // Surrogates / lambda parameter lists (shared by classic and the RD metadata shim)
    // ------------------------------------------------------------------

    public static string SurrogateName(EndpointModel ep, ParameterModel p)
        => "__KetPsi_" + Parsing.Sanitize(ep.HandlerFqn.Replace("global::", string.Empty)) + "_" + Parsing.Sanitize(p.Value.Name) + "_AsParameters";

    private static void EmitSurrogate(CodeWriter w, string name, DtoModel dto)
    {
        w.Open($"{dto.Accessibility} struct {name}");
        w.Line($"public {name}() {{ }}");
        foreach (var member in dto.ConstructorMembers.Concat(dto.PropertyMembers))
        {
            foreach (var attr in Attributes(member.Value))
                w.Line($"[{attr}]");
            var init = member.Value.DefaultLiteral ?? "default!";
            w.Line($"public {member.Value.Type.Fqn} @{member.Value.Name} {{ get; set; }} = {init};");
        }

        var ctorArgs = string.Join(", ", dto.ConstructorMembers.Select(m => "this.@" + m.Value.Name));
        var initializer = dto.PropertyMembers.Length > 0
            ? " { " + string.Join(", ", dto.PropertyMembers.Select(m => $"@{m.Value.Name} = this.@{m.Value.Name}")) + " }"
            : string.Empty;
        w.Line($"public {dto.Fqn} __ToModel() => new {dto.Fqn}({ctorArgs}){initializer};");
        w.Close();
        w.Line();
    }

    /// <summary>Canonical binding attribute plus re-created non-binding attributes.</summary>
    public static IEnumerable<string> Attributes(ValueModel value)
    {
        var binding = BindingAttribute(value.Binding);
        if (binding is not null)
            yield return binding;
        foreach (var extra in value.ExtraAttributes)
            yield return extra;
    }

    private static string? BindingAttribute(BindingSpec spec)
    {
        string Named(string type) => spec.Name is null ? type : $"{type}(Name = {Literals.String(spec.Name)})";
        return spec.Source switch
        {
            BindingSource.Route => Named("global::Microsoft.AspNetCore.Mvc.FromRouteAttribute"),
            BindingSource.Query => Named("global::Microsoft.AspNetCore.Mvc.FromQueryAttribute"),
            BindingSource.Header => Named("global::Microsoft.AspNetCore.Mvc.FromHeaderAttribute"),
            BindingSource.Form => Named("global::Microsoft.AspNetCore.Mvc.FromFormAttribute"),
            BindingSource.Body => spec.AllowEmptyBody
                ? "global::Microsoft.AspNetCore.Mvc.FromBodyAttribute(EmptyBodyBehavior = global::Microsoft.AspNetCore.Mvc.ModelBinding.EmptyBodyBehavior.Allow)"
                : "global::Microsoft.AspNetCore.Mvc.FromBodyAttribute",
            BindingSource.Services => "global::Microsoft.AspNetCore.Mvc.FromServicesAttribute",
            BindingSource.KeyedServices => spec.KeyLiteral is null ? null : $"global::Microsoft.Extensions.DependencyInjection.FromKeyedServicesAttribute({spec.KeyLiteral})",
            BindingSource.AsParameters => "global::Microsoft.AspNetCore.Http.AsParametersAttribute",
            _ => null,
        };
    }

    /// <summary>Lambda parameter declarations mirroring ExecuteAsync (used for classic lambdas and the RD metadata shim).</summary>
    public static List<string> LambdaParameters(EndpointModel ep)
    {
        var list = new List<string>();
        foreach (var p in ep.Parameters)
        {
            if (p.UseSurrogate && p.Dto is not null)
            {
                list.Add($"[global::Microsoft.AspNetCore.Http.AsParametersAttribute] {SurrogateName(ep, p)} @{p.Value.Name}");
                continue;
            }

            var attrs = string.Concat(Attributes(p.Value).Select(a => $"[{a}] "));
            var defaultPart = p.Value.DefaultLiteral is not null ? " = " + p.Value.DefaultLiteral : string.Empty;
            list.Add($"{attrs}{p.Value.Type.Fqn} @{p.Value.Name}{defaultPart}");
        }
        return list;
    }

    private static void EmitClassicRegistration(CodeWriter w, EndpointModel ep, string builderVar)
    {
        var lambdaParams = LambdaParameters(ep);
        var args = ep.Parameters.Select(p => p.UseSurrogate && p.Dto is not null ? $"@{p.Value.Name}.__ToModel()" : $"@{p.Value.Name}").ToList();

        var handlerName = "__kp_handler";
        while (ep.Parameters.Any(p => p.Value.Name == handlerName))
            handlerName = "_" + handlerName;

        if (!ep.IsStatic)
            lambdaParams.Insert(0, $"[global::Microsoft.AspNetCore.Mvc.FromServicesAttribute] {ep.HandlerFqn} {handlerName}");

        var target = ep.IsStatic ? ep.HandlerFqn : handlerName;
        var obsolete = ep.IsObsolete ? $".WithMetadata(new global::System.ObsoleteAttribute({Literals.String(ep.ObsoleteMessage)}))" : string.Empty;
        w.Line($"{builderVar}.{ep.HttpMethod}({ep.RouteTemplate}, static {ep.Return.DeclaredFqn} ({string.Join(", ", lambdaParams)}) => {target}.ExecuteAsync({string.Join(", ", args)})){obsolete}{ep.ChainTemplate};");
    }
}
